});

test('invoiceTotals sums line totals into subtotal and total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 5 * 9500 + 3 * 6000;
  const vat = Math.round(47500 * 21 / 100) + Math.round(18000 * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal + vat);
});

test('invoiceTotals with single line', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 95000;
  const vat = Math.round(95000 * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal + vat);
});

test('invoiceTotals does not mutate the invoice', () => {
