import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const number = invoice.number || 'DRAFT';

  let text = `${number}\n`;
  text += `${customerName}\n`;

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const qtyStr = String(line.qty);
    const nameStr = line.name;
    const priceStr = formatEuros(line.unitPrice);
    const totalStr = formatEuros(total);
    text += `${qtyStr} × ${nameStr} @ ${priceStr} = ${totalStr}\n`;
  }

  const totals = invoiceTotals(invoice);
  text += `Subtotal: ${formatEuros(totals.subtotal)}\n`;
  if (totals.discount > 0) {
    text += `Discount: -${formatEuros(totals.discount)}\n`;
  }
  if (totals.vat > 0) {
    text += `VAT: ${formatEuros(totals.vat)}\n`;
  }
  text += `Total: ${formatEuros(totals.total)}`;

  return text;
}
